/// <summary>
/// Jogo ativo (ETS2 ou ATS). Atualizado pela telemetria e lembrado entre aberturas do app, para que os textos
/// não voltem a "ETS2" quando o jogo está desconectado (ex.: cargas do ATS em cache).
/// </summary>
public static class TpGame
{
    private static bool _loaded;
    private static bool _isAts;

    private static string FilePath => System.IO.Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "TransPoli", "last-game.txt");

    public static bool IsAts { get { EnsureLoaded(); return _isAts; } }
    public static string Label => IsAts ? "ATS" : "ETS2";

    private static void EnsureLoaded()
    {
        if (_loaded) return;
        _loaded = true;
        try
        {
            if (System.IO.File.Exists(FilePath))
                _isAts = string.Equals(System.IO.File.ReadAllText(FilePath).Trim(), "ATS", StringComparison.OrdinalIgnoreCase);
        }
        catch { }
    }

    public static void Update(string? game)
    {
        if (string.IsNullOrWhiteSpace(game)) return;
        EnsureLoaded();
        var ats = string.Equals(game.Trim(), "ATS", StringComparison.OrdinalIgnoreCase);
        var ets = string.Equals(game.Trim(), "ETS2", StringComparison.OrdinalIgnoreCase);
        if (!ats && !ets) return;           // valor desconhecido: mantém o último jogo
        if (ats == _isAts) return;
        _isAts = ats;
        try
        {
            System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(FilePath)!);
            System.IO.File.WriteAllText(FilePath, ats ? "ATS" : "ETS2");
        }
        catch { }
    }
}

/// <summary>Fábrica/cache de geometrias dos ícones.</summary>
public static class TpIcons
{
    private static readonly Dictionary<string, Geometry> Cache = new(StringComparer.Ordinal);

    public static Geometry Get(string? kind)
    {
        if (string.IsNullOrEmpty(kind)) return Geometry.Empty;
        lock (Cache)
        {
            if (Cache.TryGetValue(kind, out var cached)) return cached;
            Geometry geometry = Geometry.Empty;
            try
            {
                if (TpIconData.Paths.TryGetValue(kind, out var path))
                {
                    geometry = Geometry.Parse(path);
                    if (geometry.CanFreeze) geometry.Freeze();
                }
            }
            catch { geometry = Geometry.Empty; }
            Cache[kind] = geometry;
            return geometry;
        }
    }

    public static bool Has(string kind) => TpIconData.Paths.ContainsKey(kind);

    /// <summary>Cria um ícone pronto para uso em código.</summary>
    public static TpIcon Create(string kind, Brush? fill = null, double size = 14) =>
        new() { Kind = kind, Fill = fill ?? Brushes.White, Width = size, Height = size };
}

/// <summary>Controle de ícone vetorial. Uso em XAML: &lt;tp:TpIcon Kind="truck" Fill="#E7B84A" Width="14" Height="14"/&gt;</summary>
public sealed class TpIcon : Viewbox
{
    public static readonly DependencyProperty KindProperty = DependencyProperty.Register(
        nameof(Kind), typeof(string), typeof(TpIcon),
        new PropertyMetadata("", (d, _) => ((TpIcon)d).Refresh()));

    public static readonly DependencyProperty FillProperty = DependencyProperty.Register(
        nameof(Fill), typeof(Brush), typeof(TpIcon),
        new PropertyMetadata(null, (d, e) => ((TpIcon)d)._path.Fill = (Brush?)e.NewValue ?? Brushes.White));

    private readonly Shapes.Path _path = new() { Fill = Brushes.White };

    public TpIcon()
    {
        // SetCurrentValue: tamanho padrão que ainda pode ser sobrescrito por Style ou atributo XAML.
        SetCurrentValue(StretchProperty, Stretch.Uniform);
        SetCurrentValue(WidthProperty, 14.0);
        SetCurrentValue(HeightProperty, 14.0);
        IsHitTestVisible = false;
        var canvas = new Canvas { Width = 24, Height = 24 };
        canvas.Children.Add(_path);
        Child = canvas;
    }

    public string Kind { get => (string)GetValue(KindProperty); set => SetValue(KindProperty, value); }
    public Brush? Fill { get => (Brush?)GetValue(FillProperty); set => SetValue(FillProperty, value); }

    private void Refresh() => _path.Data = TpIcons.Get(Kind);
}

/// <summary>
/// Camada visual global: troca emojis/símbolos por ícones vetoriais em qualquer TextBlock (inclusive o
/// texto interno de botões) e ajusta "ETS2" para "ATS" quando o jogo ativo for o ATS.
/// É à prova de falhas: se algo der errado o texto original é mantido. Desligue com TpVisuals.Enabled = false.
/// </summary>
public static class TpVisuals
{
    public static bool Enabled { get; set; } = true;

    private sealed record Glyph(string Kind, string? Color);

    private static readonly Dictionary<string, Glyph> Map = new(StringComparer.Ordinal)
    {
        ["⛽"] = new("fuel", null), ["🔒"] = new("lock", null), ["🔓"] = new("unlock", null), ["🔐"] = new("lockCheck", null),
        ["🚛"] = new("truck", null), ["🚚"] = new("truckDelivery", null), ["▣"] = new("truck", null),
        ["🟢"] = new("circle", "#4EE59B"), ["🟡"] = new("circle", "#E7B84A"), ["🔴"] = new("circle", "#FF6262"), ["🟠"] = new("circle", "#F5A524"),
        ["🧾"] = new("receipt", null), ["⭐"] = new("star", null), ["★"] = new("star", null), ["⚠"] = new("alert", null),
        ["📊"] = new("chart", null), ["💰"] = new("cash", null), ["🔧"] = new("wrench", null), ["🛠"] = new("tools", null),
        ["📚"] = new("book", null), ["📘"] = new("book", null), ["📄"] = new("doc", null), ["📋"] = new("clipboard", null),
        ["📦"] = new("cargo", null), ["⚡"] = new("bolt", null), ["⌕"] = new("search", null), ["♫"] = new("music", null), ["♪"] = new("music", null),
        ["⚖"] = new("scale", null), ["🛣"] = new("road", null), ["⭳"] = new("download", null), ["⬇"] = new("download", null),
        ["☾"] = new("moon", null), ["☀"] = new("sun", null), ["🔗"] = new("link", null), ["🛏"] = new("bed", null), ["📏"] = new("ruler", null),
        ["🕒"] = new("clock", null), ["🌡"] = new("thermo", null), ["📍"] = new("pin", null), ["⌛"] = new("hourglass", null),
        ["🛡"] = new("shield", null), ["⚙"] = new("cog", null), ["♛"] = new("trophy", null), ["♙"] = new("account", null),
        ["🛑"] = new("stopSign", null), ["📉"] = new("chartDown", null), ["🏦"] = new("bank", null), ["🔔"] = new("bell", null),
        ["◼"] = new("stop", null), ["■"] = new("stop", null), ["▶"] = new("play", null), ["Ⅱ"] = new("pause", null),
        ["↻"] = new("refresh", null), ["↺"] = new("restore", null), ["↪"] = new("logout", null), ["↗"] = new("arrowTR", null),
        ["✕"] = new("close", null), ["✓"] = new("check", null), ["⌂"] = new("home", null), ["▦"] = new("office", null),
        ["|◀"] = new("skipPrev", null), ["▶|"] = new("skipNext", null),
    };

    private static bool _installed;
    private static bool _busy;
    private static readonly ConditionalWeakTable<TextBlock, EventHandler> Watchers = new();
    private static readonly DependencyPropertyDescriptor? TextDescriptor =
        DependencyPropertyDescriptor.FromProperty(TextBlock.TextProperty, typeof(TextBlock));

    public static void Install()
    {
        if (_installed) return;
        _installed = true;
        EventManager.RegisterClassHandler(typeof(TextBlock), FrameworkElement.LoadedEvent, new RoutedEventHandler(OnLoaded));
        EventManager.RegisterClassHandler(typeof(TextBlock), FrameworkElement.UnloadedEvent, new RoutedEventHandler(OnUnloaded));
    }

    private static void OnLoaded(object sender, RoutedEventArgs e)
    {
        if (!Enabled || sender is not TextBlock tb) return;
        try
        {
            Apply(tb);
            if (TextDescriptor is null || Watchers.TryGetValue(tb, out _)) return;
            EventHandler handler = (_, _) => { if (!_busy && Enabled) { try { Apply(tb); } catch { } } };
            Watchers.Add(tb, handler);
            TextDescriptor.AddValueChanged(tb, handler);
        }
        catch { }
    }

    private static void OnUnloaded(object sender, RoutedEventArgs e)
    {
        if (sender is not TextBlock tb || TextDescriptor is null) return;
        try
        {
            if (Watchers.TryGetValue(tb, out var handler))
            {
                TextDescriptor.RemoveValueChanged(tb, handler);
                Watchers.Remove(tb);
            }
        }
        catch { }
    }

    private static bool NeedsWork(string text)
    {
        foreach (var c in text)
            if (c >= '\u2100' || char.IsSurrogate(c)) return true;
        return TpGame.IsAts && text.Contains("ETS2", StringComparison.Ordinal);
    }

    private static bool TryMatch(string s, int i, out Glyph? glyph, out int length)
    {
        glyph = null; length = 0;
        if (i + 1 < s.Length)
        {
            var two = s.Substring(i, 2);
            if (Map.TryGetValue(two, out glyph)) { length = 2; return true; }
        }
        if (char.IsHighSurrogate(s[i]) && i + 1 < s.Length)
        {
            var pair = s.Substring(i, 2);
            if (Map.TryGetValue(pair, out glyph)) { length = 2; return true; }
            return false;
        }
        if (Map.TryGetValue(s[i].ToString(), out glyph)) { length = 1; return true; }
        return false;
    }

    private static string Game(string text) => TpGame.IsAts ? text.Replace("ETS2", "ATS", StringComparison.Ordinal) : text;

    private static void Apply(TextBlock tb)
    {
        // Só mexe em texto simples (vazio ou um único Run). Conteúdo rico já montado não é tocado.
        if (tb.Inlines.Count > 1) return;
        if (tb.Inlines.Count == 1 && tb.Inlines.FirstInline is not Run) return;

        var text = tb.Text;
        if (string.IsNullOrEmpty(text) || !NeedsWork(text)) return;

        var parts = new List<Inline>();
        var buffer = new StringBuilder();
        var changed = false;
        var size = double.IsNaN(tb.FontSize) || tb.FontSize <= 0 ? 12 : tb.FontSize;

        void Flush()
        {
            if (buffer.Length == 0) return;
            parts.Add(new Run(Game(buffer.ToString())));
            buffer.Clear();
        }

        for (var i = 0; i < text.Length;)
        {
            if (text[i] == '\uFE0F') { i++; continue; }
            if (TryMatch(text, i, out var glyph, out var len) && glyph is not null && TpIcons.Has(glyph.Kind))
            {
                Flush();
                var icon = new TpIcon { Kind = glyph.Kind, Width = size * 1.2, Height = size * 1.2 };
                if (glyph.Color is not null)
                {
                    var brush = (Brush)new BrushConverter().ConvertFromString(glyph.Color)!;
                    if (brush.CanFreeze) brush.Freeze();
                    icon.Fill = brush;
                }
                else
                {
                    icon.SetBinding(TpIcon.FillProperty, new Binding("Foreground") { Source = tb });
                }
                var restIsText = i + len < text.Length && !char.IsWhiteSpace(text[i + len]);
                var gap = size * (restIsText ? 0.3 : 0.0);
                icon.Margin = new Thickness(0, 0, gap, 0);
                parts.Add(new InlineUIContainer(icon) { BaselineAlignment = BaselineAlignment.Center });
                i += len;
                changed = true;
                continue;
            }
            buffer.Append(text[i]);
            i++;
        }
        Flush();

        var gameChanged = TpGame.IsAts && text.Contains("ETS2", StringComparison.Ordinal);
        if (!changed && !gameChanged) return;

        _busy = true;
        try
        {
            tb.Inlines.Clear();
            foreach (var part in parts) tb.Inlines.Add(part);
        }
        finally { _busy = false; }
    }
}
